"use strict";const libraryElements={grid:document.getElementById("libraryGrid"),count:document.getElementById("libraryCount"),loading:document.getElementById("libraryLoading"),error:document.getElementById("libraryError")};async function initializeLibrary(){try{const r=await fetch("../data/duas.json?v=18",{cache:"no-store"});if(!r.ok)throw new Error(`Erreur HTTP ${r.status}`);const e=await r.json();if(!Array.isArray(e.categories)||!Array.isArray(e.duas))throw new Error("Le format du fichier JSON est invalide.");renderLibrary(e.categories,e.duas),libraryElements.loading.classList.add("hidden")}catch(r){console.error("Erreur bibliothèque :",r),libraryElements.loading.classList.add("hidden"),libraryElements.error.classList.remove("hidden")}}function renderLibrary(r,e){libraryElements.count.textContent=`${r.length} ${r.length>1?"thèmes":"thème"}`,libraryElements.grid.innerHTML=r.map(r=>{const n=e.filter(e=>Array.isArray(e.categories)&&e.categories.includes(r.id)).length;return`\n        <a\n          class="library-card"\n          href="../themes/${encodeURIComponent(r.id)}/"\n        >\n          <span class="library-card-icon" aria-hidden="true">\n            ${escapeHtml(r.icon||"✦")}\n          </span>\n\n          <span class="library-card-content">\n            <strong>${escapeHtml(r.label)}</strong>\n            <span>${escapeHtml(r.description||"")}</span>\n          </span>\n\n          <span class="library-card-count">\n            ${n} ${n>1?"douaas":"douaa"}\n          </span>\n        </a>\n      `}).join("")}function escapeHtml(r){return String(r??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;")}document.addEventListener("DOMContentLoaded",initializeLibrary);